def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])

    # Find the embedded contiguous line, excluding the scattered markers.
    best = None
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg or grid[r][c] == marker:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg and grid[r][c] != marker:
                c += 1
            if best is None or c - start > len(best[2]):
                best = (r, start, grid[r][start:c], "h")
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg or grid[r][c] == marker:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg and grid[r][c] != marker:
                r += 1
            if best is None or r - start > len(best[2]):
                best = (start, c, [grid[i][c] for i in range(start, r)], "v")

    out = [row[:] for row in grid]
    if best is None:
        return out

    vals, direction = best[2], best[3]
    mid = len(vals) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            for i, value in enumerate(vals):
                offset = i - mid
                rr, cc = (r, c + offset) if direction == "h" else (r + offset, c)
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
